            self._refill[name] = refill_rate
            self._parent[name] = parent
        self._tokens = dict(self._capacity)
        self._last = {name: 0.0 for name in spec}

    def allow(self, name, n=1.0, now=0.0):
        chain = []
        node = name
        while node is not None:
            chain.append(node)
            node = self._parent[node]
        for node in chain:
            if now > self._last[node]:
                self._tokens[node] = min(
                    self._capacity[node],
                    self._tokens[node] + (now - self._last[node]) * self._refill[node],
                )
                self._last[node] = now
        if all(self._tokens[node] >= n for node in chain):
            for node in chain:
                self._tokens[node] -= n
            return True
        return False

class RateTree:
    def __init__(self, spec):
        self._nodes = {}
        self._root = None
        for name, (capacity, refill_rate, parent) in spec.items():
            self._nodes[name] = {
                "capacity": capacity,
                "refill_rate": refill_rate,
                "parent": parent,
                "tokens": capacity,
                "last_update": 0.0,
            }
            if parent is None:
                self._root = name

    def _refill(self, name, now):
        node = self._nodes[name]
        if now > node["last_update"]:
            elapsed = now - node["last_update"]
            node["tokens"] = min(node["capacity"], node["tokens"] + elapsed * node["refill_rate"])
            node["last_update"] = now

    def allow(self, name, n=1.0, now=0.0):
        chain = []
        cur = name
        while cur is not None:
            chain.append(cur)
            cur = self._nodes[cur]["parent"]
        for node_name in chain:
            self._refill(node_name, now)
        if any(self._nodes[node_name]["tokens"] < n for node_name in chain):
            return False
        for node_name in chain:
            self._nodes[node_name]["tokens"] -= n
        return True

