    elif raw.endswith(")"):
        return None
    for sym in ("₹", "$", "€"):
        if raw.startswith(sym):
            raw = raw[1:].strip()
            break
    try:
        value = float(raw.replace(",", ""))
    except ValueError:
        return None
    return -value if negative else value


