def elapsed_seconds(tz_name, start, end):
    tz = ZoneInfo(tz_name)

    def to_utc(dt):
        naive = dt.replace(tzinfo=None)
        first = naive.replace(tzinfo=tz, fold=0)
        second = naive.replace(tzinfo=tz, fold=1)
        if first.utcoffset() != second.utcoffset():
            return first.astimezone(timezone.utc)
        utc = first.astimezone(timezone.utc)
        if utc.astimezone(tz).replace(tzinfo=None) == naive:
            return utc
        pre_offset = (naive - timedelta(microseconds=1)).replace(tzinfo=tz, fold=0).utcoffset()
        return (naive - pre_offset).replace(tzinfo=timezone.utc)

    start_dt = datetime.strptime(start, "%Y-%m-%d %H:%M:%S")
    end_dt = datetime.strptime(end, "%Y-%m-%d %H:%M:%S")
    return (to_utc(end_dt) - to_utc(start_dt)).total_seconds()

